    }

    func runTextTurn(_ context: AssistantTurnContext) async throws -> String {
        switch context.task {
        case .embedding, .safetyClassification:
            throw KernelError.unsupportedTaskForTextTurn(context.task)
        default:
            break
        }
        let selection = router.selection(for: context)
        guard selection.runtime != .coreML else { throw KernelError.unsupportedRuntimeForTextTurn(.coreML) }","language":"swift","lineEnd":51,"lineStart":1,"module":"Assistant","path":"ios/Lumen/Assistant/AssistantKernel.swift","sourceHash":"b11c3c703c44e6693287cfb4fc967cc398722caaa8a3b3bbfe77e61fb677ca5e"}

