    func refreshFindings(storageChecks: [(String, Bool)] = []) {
        var next: [DeveloperFinding] = [
            DeveloperFinding(
                severity: .info,
                title: "Live E2E is authoritative",
                detail: "`e2eTestReport` is the only evidence layer that owns live scenario pass/fail."
            ),
            DeveloperFinding(
