        } else {
            baseError = error
        }
        let nsError = baseError as NSError
        return FailureContext(stage: stage, message: nsError.localizedDescription, domain: nsError.domain, code: nsError.code)
    }

    func continueInLimitedMode(appState: AppState) {
        do {
