    init(title: String, prompt: String, scheduleType: TriggerScheduleType, fireDate: Date? = nil, timeOfDayMinutes: Int? = nil, intervalSeconds: TimeInterval? = nil, weekdayMask: Int = 0, beforeNextEventMinutes: Int? = nil) {
