        }","language":"swift","lineEnd":43,"lineStart":1,"module":"Services/LLM","path":"ios/Lumen/Services/LLM/ModelThinkingControl.swift","sourceHash":"2c63b1f5ef8b6f7ab3779f4ddbc32a4969c5339cd47743c4aaef6c183f16cf2a"}

