    var isAllowed: Bool {
        switch self {
        case .allowed, .downgraded:
            return true
        case .rejected:
            return false
        }
    }

    var isRejected: Bool {
        if case .rejected = self {
            return true
        }
        return false
    }

    var report: ModelFitReport {
        switch self {
        case .allowed(let report), .downgraded(let report), .rejected(let report):
            return report
        }
    }
}

