private final class LlamaRuntimeStopFlag: @unchecked Sendable {
    private let lock = NSLock()
    private var requested = false

    func requestStop() {
        lock.lock()
        requested = true
        lock.unlock()
    }

    func reset() {
        lock.lock()
        requested = false
        lock.unlock()
    }

    var isStopRequested: Bool {
        lock.lock()
        defer { lock.unlock() }
        return requested
    }
}

