            let response = try await MKLocalSearch(request: request).start()","language":"swift","lineEnd":59,"lineStart":1,"module":"Services/Tools","path":"ios/Lumen/Services/Tools/LocationTools.swift","sourceHash":"3abcbb1cb58de8dff62164b4acb186cbc25f2483f0e85597e40137a71988e65c"}

