{"boundary":"This is static tracked source text. Use it for source grounding only; do not infer private runtime state from it.","chunkCount":7,"chunkHash":"1b5f6f577366bcd8c24757f90efd7e37173e93cf12ff1af835cf1825d8c8a287","chunkIndex":6,"chunkText":"    private func attachStepSnapshot(stepName: String, status: String, durationMs: Int, errorMessage: String?) {
        let payload = [
            "step": stepName,
            "status": status,
            "durationMs": String(durationMs),
            "error": errorMessage ?? ""
        ]
            .map { "\($0.key)=\($0.value)" }
            .joined(separator: "\n")

        let attachment = XCTAttachment(string: payload)
        attachment.name = "Live Step \(stepName)"
        attachment.lifetime = .keepAlways
        add(attachment)
    }

    private func percentileDuration(from steps: [DashboardStep], percentile: Double) -> Double {
        let sorted = steps.map(\.durationMs).sorted()
        guard !sorted.isEmpty else { return 0 }
        let index = min(max(Int(Double(sorted.count - 1) * percentile), 0), sorted.count - 1)
        return Double(sorted[index])
    }

    private func maxDuration(from steps: [DashboardStep]) -> Double {
        Double(steps.map(\.durationMs).max() ?? 0)
    }
