                routed_sft[agent].append(sft_record)
                routing_stats[agent]["sourceFamilies"].add(source_family)
                routing_stats[agent]["taskTypes"].add(normalized["taskType"])
                routing_stats[agent]["availableSFTRecords"] += 1

