            if key_l in {"tool", "toolid", "selectedtoolid", "rejectedtoolid", "validreplacement", "invalidoutput"} and isinstance(child, str):
                found.add(child)
            else:
                found.update(_extract_tool_ids(child))
    elif isinstance(value, list):
        for child in value:
            found.update(_extract_tool_ids(child))
    return found


