def _framework_job_env(root: Path) -> dict[str, str]:
    env = os.environ.copy()
    pythonpath_entries = [
        str((root / "tools/lumen_manifest_crawler").resolve()),
        str(root.resolve()),
    ]
    existing = env.get("PYTHONPATH")
    env["PYTHONPATH"] = os.pathsep.join(pythonpath_entries + ([existing] if existing else []))
