import re

from lumen_manifest_crawler.swift_extractors.base import SwiftExtractor, SwiftFile, string_literals


DEFAULT_FORBIDDEN = {
    "[REDACTED_SENTINEL]",
    "[REDACTED_SENTINEL]",
    "[REDACTED_SENTINEL]",
    "[REDACTED_SENTINEL]",
    "[REDACTED_SENTINEL]",
    "[REDACTED_SENTINEL]",
}
SENTINEL_WORDS = {
    "final",
    "hidden",
    "internal",
    "private",
    "reasoning",
    "scratchpad",
    "state",
    "tool",
    "user",
}


class SentinelExtractor(SwiftExtractor):
    target_names = ("ChatView.swift", "AgentService.swift", "ComposeController.swift")

    def extract(self, file: SwiftFile, manifest) -> None:
        found = set(manifest.sentinels.forbiddenInUserOutput)
        found.update(DEFAULT_FORBIDDEN)
        for literal in string_literals(file.text):
            lowered = literal.lower()
            if self._looks_like_internal_sentinel(lowered):
                found.add(literal)
            if "private_reasoning" in lowered or "scratchpad" in lowered or "internal_state" in lowered:
                found.add(literal)
        manifest.sentinels.forbiddenInUserOutput = sorted(found)

    @staticmethod
    def _looks_like_internal_sentinel(value: str) -> bool:
        if not re.fullmatch(r"<[a-z0-9_\-]+>", value):
            return False
        inner = value[1:-1]
        tokens = set(re.split(r"[_\-]+", inner))
        return bool(tokens.intersection(SENTINEL_WORDS))","imports":["__future__","re","lumen_manifest_crawler.swift_extractors.base"],"language":"python","module":"tools/lumen_manifest_crawler/lumen_manifest_crawler","path":"tools/lumen_manifest_crawler/lumen_manifest_crawler/swift_extractors/sentinels.py","responsibility":"`tools/lumen_manifest_crawler/lumen_manifest_crawler/swift_extractors/sentinels.py` owns sentinels behavior and defines: SentinelExtractor, extract, _looks_like_internal_sentinel.","sourceHash":"395fbef433e9ec7015c44f370da105f31a73ef6bf20bc486bfd37cd626d9f147","symbols":["SentinelExtractor","extract","_looks_like_internal_sentinel"]}

